    "difficulty": "easy",
    "questionEn": "If the line of action of the force $\\vec{F} = k\\hat{i} + 3\\hat{j}$ passing through $A(2, 3)$ passes through the origin $O$, find the value of $k$.",
    "questionAr": "إذا كان خط عمل القوة $\\vec{F} = k\\hat{i} + 3\\hat{j}$ المارة بالنقطة $A(2, 3)$ يمر بنقطة الأصل $O$، فإن قيمة $k$ تساوي:",
