    "questionAr": "تؤثر القوة $\\vec{F} = 2\\hat{i} + m\\hat{j}$ في مستوى النقطتين $A(1, 2)$ و $B(4, 5)$. إذا كان عزم القوة حول $A$ يساوي عزمها حول $B$ (أي $\\vec{M}_A = \\vec{M}_B \\ne \\vec{0}$)، فإن قيمة $m$ تساوي:",
