    "questionAr": "تؤثر قوة مقدارها $F = 21\\text{ نيوتن}$ في اتجاه القطعة المستقيمة الموجهة $\\vec{AB}$ حيث $A(0, 0, 0)$ و $B(2, 3, 6)$. أوجد مركبة عزم القوة حول محور ع بالنسبة للنقطة $C(1, 2, 0)$ (أي $M_z$).",
