    "hintEn": "Find the unit vector $\\hat{u}_{AB} = \\frac{\\vec{AB}}{\\|\\vec{AB}\\|}$, then $\\vec{F} = F \\hat{u}_{AB}$, and $\\vec{M}_C = \\vec{CA} \\times \\vec{F}$.",
    "hintAr": "أوجد متجه الوحدة $\\hat{u}_{AB} = \\frac{\\vec{AB}}{\\|\\vec{AB}\\|}$، ثم $\\vec{F} = F \\hat{u}_{AB}$، وبعدها $\\vec{M}_C = \\vec{CA} \\times \\vec{F}$.",
