      "2. Expanding: $\\vec{M}_O = (64)\\hat{i} - (48)\\hat{k}\\text{ N}\\cdot\\text{m}$.",
      "3. Magnitude: $\\|\\vec{M}_O\\| = \\sqrt{(64)^2 + (-48)^2} = 5 \\times 16 = 80\\text{ N}\\cdot\\text{m}$.",
      "4. Force magnitude: $\\|\\vec{F}\\| = \\sqrt{3^2 + 0^2 + 4^2} = 5\\text{ N}$.",
      "5. Distance: $L = \\frac{\\|\\vec{M}_O\\|}{\\|\\vec{F}\\|} = \\frac{80}{5} = 16\\text{ m}$."
