    "difficulty": "hots",
    "questionEn": "A light rod $AB$ has length $L = 10\\text{ cm}$. A vertical upward force of $20\\text{ N}$ acts at end $B$. At what distance $x$ from end $A$ must a downward force of $5\\text{ N}$ be placed so that the total moment of the forces about $A$ is zero?",
    "questionAr": "ساق خفيفة $AB$ طولها $L = 10\\text{ سم}$. تؤثر قوة رأسية لأعلى مقدارها $20\\text{ نيوتن}$ عند الطرف $B$. على أي بعد $x$ من الطرف $A$ يجب وضع قوة رأسية لأسفل مقدارها $5\\text{ نيوتن}$ لكي ينعدم المجموع الجبري لعزوم القوى حول $A$؟",
    "optionsEn": [
      "$40\\text{ cm}$",
      "$50\\text{ cm}$",
      "$60\\text{ cm}$",
      "$70\\text{ cm}$"
    ],
    "optionsAr": [
      "40 سم",
      "50 سم",
      "60 سم",
      "70 سم"
    ],
    "correctAnswer": "$40\\text{ cm}$",
    "correctIndex": 0,
    "hintEn": "Set the algebraic sum of moments about $A$ to zero: $\\sum M_A = 20 \\times L - 5 \\times x = 0$.",
    "hintAr": "اجعل المجموع الجبري للعزوم حول $A$ مساوياً للصفر: $\\sum M_A = 20 \\times L - 5 \\times x = 0$.",
    "stepByStepSolutionEn": [
      "1. Taking moments about $A$: the upward force at $B$ produces a counterclockwise moment $+20 \\times 10 = 200\\text{ N}\\cdot\\text{cm}$.",
      "2. The downward force of $5\\text{ N}$ produces a clockwise moment $-5 \\times x$.",
      "3. Condition $\\sum M_A = 0 \\implies 200 - 5x = 0$.",
      "4. Solve for $x$: $x = \\frac{200}{5} = 40\\text{ cm}$."
    ],
    "stepByStepSolutionAr": [
      "١. بأخذ العزوم حول $A$: القوة لأعلى عند $B$ عزمها $+20 \\times 10 = 200\\text{ نيوتن.سم}$.",
      "٢. القوة لأسفل عند بعد $x$ عزمها $-5 \\times x$.",
      "٣. شرط انعدام العزم: $20(10) - 5x = 0$.",
      "٤. إذن $x = \\frac{200}{5} = 40\\text{ سم}$."
    ],
    "teacherTipEn": "Take moments about A to eliminate forces acting directly at A.",
    "teacherTipAr": "أخذ العزوم حول نقطة يلغي عزم أي قوة تمر بها."
